const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object') ? raw.body : (raw || {});
const errors = [];

if (!input.videoUrl || typeof input.videoUrl !== 'string' || !input.videoUrl.trim().startsWith('http')) {
  errors.push('A valid videoUrl starting with http:// or https:// is required.');
}

if (!input.musicUrl || typeof input.musicUrl !== 'string' || !input.musicUrl.trim().startsWith('http')) {
  errors.push('A valid musicUrl starting with http:// or https:// is required.');
}

if (!input.text || typeof input.text !== 'string' || input.text.trim().length < 3) {
  errors.push('Motivational text must be at least 3 characters long.');
}

const duration = Number(input.durationSeconds) || 30;
if (duration < 5 || duration > 120) {
  errors.push('durationSeconds must be between 5 and 120.');
}

const width = Number(input.width) || 1080;
const height = Number(input.height) || 1920;
const style = input.style || 'dark-motivational';
const title = (input.title || 'Motivational Short').trim();

// Determine FastAPI public endpoint (provided by frontend payload or tunnel fallback)
const defaultFallback = 'https://disclose-oil-half-spending.trycloudflare.com';
const fastApiBaseUrl = (input.fastApiBaseUrl || defaultFallback).trim().replace(/\/$/, '');
const apiKey = (input.apiKey || 'dev-shorts-secret-key-2024').trim();

// Publishing options
const publishPlatforms = Object.assign({
  youtube: true,
  discord: true,
  telegram: true,
  instagram: true
}, input.publishPlatforms || input.platforms || {});

const youtubePrivacy = (input.youtubePrivacy || 'private').toLowerCase();
const spreadsheetUrl = input.spreadsheetUrl || input.spreadsheetId || null;
const rowNumber = input.rowNumber ? Number(input.rowNumber) : null;
const sheetName = input.sheetName || null;

if (errors.length > 0) {
  return [{
    json: {
      isValid: false,
      errors: errors,
      fastApiBaseUrl: fastApiBaseUrl,
      apiKey: apiKey
    }
  }];
}

return [{
  json: {
    isValid: true,
    videoUrl: input.videoUrl.trim(),
    musicUrl: input.musicUrl.trim(),
    text: input.text.trim(),
    title: title,
    durationSeconds: duration,
    width: width,
    height: height,
    style: style,
    fastApiBaseUrl: fastApiBaseUrl,
    apiKey: apiKey,
    publishPlatforms: publishPlatforms,
    youtubePrivacy: youtubePrivacy,
    spreadsheetUrl: spreadsheetUrl,
    rowNumber: rowNumber,
    sheetName: sheetName
  }
}];

