const original = $('Validate Input').first().json;
const renderOutput = $('Render Short (FFmpeg)').first().json;
const binaryItem = $input.first();
const binaryData = binaryItem && binaryItem.binary ? binaryItem.binary : null;

const title = original.title || 'Motivational Short';
const quote = original.text || 'Keep pushing forward.';
const videoUrl = renderOutput.videoUrl || '';
const downloadUrl = renderOutput.downloadUrl || videoUrl;
const fastApiBaseUrl = original.fastApiBaseUrl;
const apiKey = original.apiKey;

// Platform specific captions (Consistent motivational quote across all platforms)
const youtubeTitle = (title + ' #Shorts').substring(0, 95);
const youtubeDescription = `"${quote}"\n\nTransform your mindset, stay disciplined, and rise above limits.\n\n#Shorts #Motivation #Success #Inspiration #Mindset`;
const youtubeTags = ['Shorts', 'Motivation', 'Success', 'Inspiration', 'Mindset'];

const discordContent = `**${title}**\n\n> "${quote}"\n\n#Shorts #Motivation #Success`;
const telegramCaption = `🎬 **${title}**\n\n❝ ${quote} ❞\n\n#Shorts #Motivation #Success #Discipline`;
const instagramCaption = `${title}\n\n❝ ${quote} ❞\n.\n.\n#shorts #motivation #success #mindset #reels #growth`;

const payload = {
  title: title,
  quote: quote,
  videoUrl: videoUrl,
  downloadUrl: downloadUrl,
  fastApiBaseUrl: fastApiBaseUrl,
  apiKey: apiKey,
  publishPlatforms: original.publishPlatforms || { youtube: true, discord: true, telegram: true, instagram: true },
  youtubePrivacy: original.youtubePrivacy || 'private',
  spreadsheetUrl: original.spreadsheetUrl,
  rowNumber: original.rowNumber,
  sheetName: original.sheetName,
  captions: {
    youtube: { title: youtubeTitle, description: youtubeDescription, tags: youtubeTags },
    discord: { content: discordContent },
    telegram: { caption: telegramCaption },
    instagram: { caption: instagramCaption }
  }
};

const outItem = { json: payload };
if (binaryData) {
  outItem.binary = binaryData;
}
return [outItem];

