const original = $('Validate Input').first().json;
const renderInfo = $('Render Short (FFmpeg)').first().json;

// Collect formatted results from each independent branch
let ytResult = { status: 'Skipped', videoId: '', url: '', error: null };
let dcResult = { status: 'Skipped', messageId: '', url: '', error: null };
let tgResult = { status: 'Skipped', messageId: '', error: null };
let igResult = { status: 'Skipped', mediaId: '', url: '', error: null };

try {
  ytResult = $('Format YouTube Result').first().json;
} catch (e) {}

try {
  dcResult = $('Format Discord Result').first().json;
} catch (e) {}

try {
  tgResult = $('Format Telegram Result').first().json;
} catch (e) {}

try {
  igResult = $('Format Instagram Result').first().json;
} catch (e) {}

const platformList = [ytResult, dcResult, tgResult, igResult];
const activePlatforms = platformList.filter(p => p.status !== 'Skipped');

let overallStatus = 'Skipped';
if (activePlatforms.length > 0) {
  const successCount = activePlatforms.filter(p => p.status === 'Published').length;
  const failCount = activePlatforms.filter(p => p.status === 'Failed').length;

  if (successCount === activePlatforms.length) {
    overallStatus = 'Completed';
  } else if (successCount > 0) {
    overallStatus = 'Partially Completed';
  } else {
    overallStatus = 'Failed';
  }
}

const timestamp = new Date().toISOString();

const sheetData = {
  youtube_status: ytResult.status || 'Skipped',
  youtube_video_id: ytResult.videoId || '',
  youtube_url: ytResult.url || '',
  discord_status: dcResult.status || 'Skipped',
  discord_message_id: dcResult.messageId || '',
  telegram_status: tgResult.status || 'Skipped',
  telegram_message_id: tgResult.messageId || '',
  instagram_status: igResult.status || 'Skipped',
  instagram_media_id: igResult.mediaId || '',
  instagram_url: igResult.url || '',
  overall_publish_status: overallStatus,
  last_publish_attempt: timestamp
};

return [{
  json: {
    fastApiBaseUrl: original.fastApiBaseUrl,
    apiKey: original.apiKey,
    spreadsheetUrl: original.spreadsheetUrl,
    rowNumber: original.rowNumber,
    sheetName: original.sheetName,
    jobId: renderInfo.jobId || ('job_' + Math.random().toString(36).substring(2, 9)),
    videoUrl: renderInfo.videoUrl || '',
    downloadUrl: renderInfo.downloadUrl || renderInfo.videoUrl || '',
    title: original.title || 'Motivational Short',
    durationSeconds: Number(original.durationSeconds || 30),
    overall_publish_status: overallStatus,
    last_publish_attempt: timestamp,
    publishingResults: {
      youtube: ytResult,
      discord: dcResult,
      telegram: tgResult,
      instagram: igResult
    },
    sheetData: sheetData
  }
}];

